/** PostgreSQL database, schema ownership, and read-only SQLite import. */
import { DatabaseSync, type SQLInputValue } from 'node:sqlite'
import { realpathSync } from 'node:fs'
import { startWorkerThread } from 'synckit'
import { fileURLToPath } from 'node:url'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import type { StoreDatabase } from './database.ts'
import { postgresSql } from './database.ts'
import { SCHEMA_VERSION } from './migration.ts'
import { Store } from './store.ts'
import type { Request, Response } from './postgres-worker.ts'

/** Database failures stop dependent work; a lost connection is never reconnected or retried. */
export class DatabaseError extends HarnessError {
  constructor(message: string, code: 'SUPERAGENT_DATABASE_CONFIG' | 'SUPERAGENT_DATABASE_FAILED' | 'SUPERAGENT_DATABASE_IMPORT', options?: ErrorOptions) {
    super(message, code, options)
    this.name = 'DatabaseError'
  }
}

/** Dedicated schema; ordering identities preserve the SQLite insertion order across upserts. */
const SCHEMA = `
CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trigger (id TEXT PRIMARY KEY, value TEXT NOT NULL, at TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS disposition (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS thread (key TEXT PRIMARY KEY, value TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
 active INTEGER GENERATED ALWAYS AS (CASE WHEN jsonb_array_length(value::jsonb -> 'pending') > 0 OR value::jsonb -> 'evaluating' IS NOT NULL THEN 1 END) STORED,
 subscribed TEXT GENERATED ALWAYS AS (CASE WHEN jsonb_array_length(value::jsonb -> 'subscriptions') > 0 THEN value::jsonb #>> '{ref,source}' END) STORED);
CREATE TABLE IF NOT EXISTS ticket (id TEXT PRIMARY KEY, value TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
 open INTEGER GENERATED ALWAYS AS (CASE WHEN value::jsonb -> 'ended' IS NULL THEN 1 END) STORED,
 active INTEGER GENERATED ALWAYS AS (CASE WHEN jsonb_array_length(value::jsonb -> 'undelivered') > 0 OR value::jsonb #>> '{assignments,-1,state}' IN ('pending', 'running') THEN 1 END) STORED);
CREATE TABLE IF NOT EXISTS decision (id TEXT PRIMARY KEY, thread TEXT NOT NULL, value TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, value TEXT NOT NULL, rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
 dropped TEXT GENERATED ALWAYS AS (value::jsonb #>> '{dropped,at}') STORED,
 pending TEXT GENERATED ALWAYS AS (CASE WHEN value::jsonb ->> 'status' = 'pending' AND value::jsonb ->> 'ticketId' IS NOT NULL
 THEN (value::jsonb ->> 'ticketId') || ' ' || (value::jsonb #>> '{channel,thread}') END) STORED);
CREATE TABLE IF NOT EXISTS trigger_thread (thread TEXT NOT NULL, id TEXT NOT NULL, at TEXT NOT NULL, human INTEGER NOT NULL, PRIMARY KEY(thread,id));
CREATE TABLE IF NOT EXISTS effect (kind TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, seq BIGINT NOT NULL,
 generation INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', due BIGINT NOT NULL, since TEXT NOT NULL, PRIMARY KEY(kind,key));
CREATE INDEX IF NOT EXISTS trigger_at ON trigger(at);
CREATE INDEX IF NOT EXISTS trigger_thread_at ON trigger_thread(thread,at);
CREATE INDEX IF NOT EXISTS decision_thread ON decision(thread);
CREATE INDEX IF NOT EXISTS effect_due ON effect(kind,due,seq);
CREATE INDEX IF NOT EXISTS ticket_open ON ticket(open) WHERE open IS NOT NULL;
CREATE INDEX IF NOT EXISTS ticket_active ON ticket(active) WHERE active IS NOT NULL;
CREATE INDEX IF NOT EXISTS thread_active ON thread(active) WHERE active IS NOT NULL;
CREATE INDEX IF NOT EXISTS thread_subscribed ON thread(subscribed) WHERE subscribed IS NOT NULL;
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(pending) WHERE pending IS NOT NULL;
CREATE INDEX IF NOT EXISTS outbox_dropped ON outbox(dropped) WHERE dropped IS NOT NULL;
`

/** A single PostgreSQL session, including the advisory lock, is owned until close.
 * The worker keeps network I/O off this synchronous repository interface. Each operation blocks the
 * caller until PostgreSQL replies; connection loss or an unknown outcome permanently disables this instance.
 */
export class PostgresDatabase implements StoreDatabase {
  readonly dialect = 'postgres'
  private readonly call: (request: Request) => Response
  private closed = false
  private broken = false
  constructor(url: string, timeoutMs: number, schema = 'dsh_superagent') {
    if (!/^[a-z_][a-z0-9_]{0,62}$/.test(schema)) throw new DatabaseError('databaseSchema must be a lowercase PostgreSQL identifier of at most 63 characters.', 'SUPERAGENT_DATABASE_CONFIG')
    this.call = startWorkerThread<(request: Request) => Promise<Response>>(fileURLToPath(new URL(import.meta.url.endsWith('.ts') ? './postgres-worker.ts' : './postgres-worker.js', import.meta.url)), { timeout: timeoutMs + 5000 })
    try {
      this.request({ kind: 'open', url, timeoutMs })
      if (!this.prepare("SELECT CASE WHEN pg_try_advisory_lock(1936942695, hashtext(?)) THEN 1 ELSE 0 END AS locked").get(schema)?.locked) throw new Error('Another Superagent owns this PostgreSQL database')
      this.exec('BEGIN')
      try {
        this.exec(`CREATE SCHEMA IF NOT EXISTS "${schema}"; SET search_path TO "${schema}", pg_catalog`)
        this.exec('CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT NOT NULL)')
        const version = this.prepare("SELECT value FROM kv WHERE key = 'schema'").get()?.value
        if (version !== undefined && JSON.parse(String(version)) !== SCHEMA_VERSION) throw new Error(`Unsupported PostgreSQL orchestrator schema; expected ${SCHEMA_VERSION}`)
        this.exec(SCHEMA)
        this.prepare("INSERT INTO kv(key,value) VALUES ('schema', ?) ON CONFLICT DO NOTHING").run(String(SCHEMA_VERSION))
        this.exec('COMMIT')
      } catch (error) { this.exec('ROLLBACK'); throw error }
    } catch (error) {
      this.close()
      throw new DatabaseError('Could not open the PostgreSQL store. Check its availability, schema version, and single-writer ownership.', 'SUPERAGENT_DATABASE_FAILED', { cause: error })
    }
  }
  private request(request: Request): Response {
    if (this.closed || this.broken) throw new DatabaseError('PostgreSQL store is unavailable; stop dependent work and restart after checking the database.', 'SUPERAGENT_DATABASE_FAILED')
    let response: Response
    try { response = this.call(request) }
    catch (error) {
      this.broken = true
      throw new DatabaseError('PostgreSQL worker failed; the last write may have committed. Stop dependent work and check the database before restarting.', 'SUPERAGENT_DATABASE_FAILED', { cause: error })
    }
    if (response.error) {
      if (response.fatal) this.broken = true
      throw new DatabaseError(response.fatal
        ? 'PostgreSQL connection was lost; the last write may have committed. Stop dependent work and check the database before restarting.'
        : `PostgreSQL rejected the operation (${response.error}); check the database schema and configuration.`, 'SUPERAGENT_DATABASE_FAILED')
    }
    return response
  }
  /** Execute trusted schema or transaction SQL; no automatic retry follows any failure. */
  exec(sql: string): void { this.request({ kind: 'query', sql }) }
  /** Prepare one of the store's parameterized queries; values never enter SQL text. */
  prepare(sql: string): ReturnType<StoreDatabase['prepare']> {
    const query = (...values: SQLInputValue[]) => this.request({ kind: 'query', sql: postgresSql(sql), values })
    return {
      all: (...values: SQLInputValue[]) => query(...values).rows,
      get: (...values: SQLInputValue[]) => query(...values).rows[0],
      run: (...values: SQLInputValue[]) => ({ changes: query(...values).changes, lastInsertRowid: 0 }),
    }
  }
  /** Wait for the session to close, releasing its lock; repeated close is harmless. */
  close(): void {
    if (this.closed) return
    try { this.call({ kind: 'close' }) }
    finally { this.closed = true }
  }
}

const TABLES = {
  kv: ['key', 'value'], trigger: ['id', 'value', 'at'], disposition: ['id', 'value'], thread: ['key', 'value'],
  ticket: ['id', 'value'], decision: ['id', 'thread', 'value'], outbox: ['id', 'value'],
  trigger_thread: ['thread', 'id', 'at', 'human'], effect: ['kind', 'key', 'value', 'seq', 'generation', 'attempts', 'error', 'due', 'since'],
} as const
const IMPORT_KEY = 'postgres/sqlite-import'

/** Import a stopped schema-11 SQLite store once; source rows and files remain unchanged.
 * @param store - Empty PostgreSQL destination with exclusive ownership.
 * @param path - Source database, protected by the runtime's state-directory lock.
 * @returns Nothing; all rows and the completion marker commit together, or none do. Repeating the same completed import is a no-op; other nonempty destinations are refused.
 */
export function importSqlite(store: Store, path: string): void {
  const source = realpathSync(path)
  const imported = store.get<{ source: string }>(IMPORT_KEY)
  if (imported) {
    if (imported.source !== source) throw new DatabaseError('PostgreSQL already contains an import from another SQLite path.', 'SUPERAGENT_DATABASE_IMPORT')
    return
  }
  const sqlite = new DatabaseSync(source, { readOnly: true })
  try {
    sqlite.exec('BEGIN')
    const version = sqlite.prepare("SELECT value FROM kv WHERE key = 'schema'").get()?.value
    if (version === undefined || JSON.parse(String(version)) !== SCHEMA_VERSION) throw new DatabaseError(`Open SQLite with the current build first; import requires schema ${SCHEMA_VERSION}.`, 'SUPERAGENT_DATABASE_IMPORT')
    store.atomic(() => {
      for (const [table, columns] of Object.entries(TABLES)) {
        const where = table === 'kv' ? " WHERE key <> 'schema'" : ''
        if (Number(store.db.prepare(`SELECT COUNT(*) AS n FROM ${table}${where}`).get()?.n)) throw new DatabaseError('SQLite import requires an empty PostgreSQL store; existing rows were preserved.', 'SUPERAGENT_DATABASE_IMPORT')
        const insert = store.db.prepare(`INSERT INTO ${table} (${columns.join(',')}) VALUES (${columns.map(() => '?').join(',')})`)
        for (const row of sqlite.prepare(`SELECT ${columns.join(',')} FROM ${table} ORDER BY rowid`).all()) {
          if (table === 'kv' && row.key === 'schema') continue
          insert.run(...columns.map(column => row[column]!))
        }
      }
      store.set(IMPORT_KEY, { source })
    })
  } finally { sqlite.close() }
}
